// follows the registered red line exactly.
const mouth=Array.from({length:9},(_,i)=>{const t=i/8,q=1-t;return tip.map((v,k)=>q*q*q*v+3*q*q*t*c1[k]+3*q*t*t*c2[k]+t*t*t*join[k]);});
