  for(const z of [-10.6,-7,3.6,17.1])opening('mast-side long elevation',-17.77,z,-Math.PI/2,1.05,2.8);
  for(const z of [7,10.7,14.5])opening('low side room',-20.47,z,-Math.PI/2,1.05,1.7,2.1);
