  solid(dark,11.1,4.72,-14.6,4.4,.28,5.1,'Entrance flat canopy');
  solid(glass,11.1,2.2,-17.04,3.2,4.25,.1,'Glazed entrance');
  for(const x of [9.55,11.1,12.65])box(frame,x,2.2,-17.15,.08,4.4,.1);
