  for(const [x,z,y,w] of [[-13,-7,8.1,1.1],[-12,12,8.6,1.3],[15,-10,7.1,1.2],[17,3,7.3,1.1],[4,-6,7.4,1.2],[-1,-5,7.5,1.2]]){
