    const x=px/(resolution-1)*2-1,y=py/(resolution-1)*2-1,index=(py*resolution+px)*4;
    let shade=0;
    if(Math.abs(x-.018*Math.sin(y*8))<.014&&y>-.92&&y<.85)shade=115;
