 #ifdef USE_INSTANCING
  groundWorldPosition = instanceMatrix * groundWorldPosition;
 #endif
 groundWorldPosition = modelMatrix * groundWorldPosition;
 vec2 groundUv = groundWorldPosition.xz / ${TILE_SIZE.toFixed(1)};
 #ifdef USE_MAP
  vMapUv = groundUv;
 #endif
 #ifdef USE_BUMPMAP
  vBumpMapUv = groundUv;
