   const dx=(b[0]-a[0])/length*padding,dz=(b[1]-a[1])/length*padding;
   footprints.push([[a[0]-dx-dz,a[1]-dz+dx],[b[0]+dx-dz,b[1]+dz+dx],[b[0]+dx+dz,b[1]+dz-dx],[a[0]-dx+dz,a[1]-dz-dx]]);
