 'main-kitchen':{position:[105,77,49],target:[137,3,-10],fov:46},
 'main-kitchen-plan':{position:[137,106,-9.99],target:[137,0,-10],fov:46},
 'main-kitchen-roofs':{position:[138,22,47],target:[137,5,-10],fov:44}
});
