    branch([Math.sin(a)*r,-.2,Math.cos(a)*r],[Math.sin(a)*.4,.85,Math.cos(a)*.4],.13,.4);
  }
  for(let n=0;n<10;n++){
    const a=n*2.39996,reach=spec.radius*(.54+random()*.16),height=7.6+random()*5.8;
    const elbow=[Math.sin(a)*reach*.52,5.9+(n%3),Math.cos(a)*reach*.52];
