    const positions=[],uv=[];
    for(const face of [[0,1,6],[1,2,6],[2,3,7],[2,7,6],[3,4,7],[4,5,7],[5,0,6],[5,6,7]])for(const i of [...face].reverse()){positions.push(...vertices[i]);uv.push(vertices[i][0]/3,vertices[i][2]/3);}
